styles:
:root{--bg:#070707;--bg2:#0d0d0d;--panel:#111;--paper:#f1eee7;--text:#f5f2ec;--muted:#a7a39c;--line:rgba(255,255,255,.14);--red:#e81848;--teal:#27a3a2;--teal-bright:#45c0bd;--pad:clamp(20px,3.35vw,58px);--max:1480px;--ease:cubic-bezier(.16,1,.3,1);--font:"Helvetica Neue",Helvetica,Arial,sans-serif}
*{box-sizing:border-box}html{scroll-behavior:smooth;background:var(--bg)}body{margin:0;background:var(--bg);color:var(--text);font-family:var(--font);font-size:16px;line-height:1.5;overflow-x:hidden}body.menu-open{overflow:hidden}a{color:inherit;text-decoration:none}img{display:block;width:100%}button,input{font:inherit}.shell{width:min(var(--max),100%);margin:auto;padding-inline:var(--pad)}
.skip{position:fixed;left:12px;top:12px;z-index:200;background:var(--paper);color:#111;padding:10px 14px;transform:translateY(-150%)}.skip:focus{transform:none}.nav{height:82px;position:fixed;inset:0 0 auto;z-index:90;display:grid;grid-template-columns:auto 1fr auto;align-items:center;padding:0 var(--pad);background:rgba(7,7,7,.76);backdrop-filter:blur(16px);border-bottom:1px solid rgba(255,255,255,.08)}.brand{display:flex;align-items:center;gap:10px;font-weight:700;font-size:18px;letter-spacing:-.04em}.brand img{width:29px;height:29px;object-fit:contain}.nav-links{justify-self:end;display:flex;align-items:center;gap:clamp(18px,2vw,34px);font-size:13px}.nav-links a{color:#d8d5d0}.nav-links a:hover,.nav-links a:focus-visible{color:white}.nav-cta{border:1px solid rgba(255,255,255,.26);padding:11px 16px}.menu-btn{display:none;width:46px;height:46px;background:none;border:1px solid rgba(255,255,255,.2);color:white;position:relative}.menu-btn:before,.menu-btn span{content:"";position:absolute;left:13px;width:18px;height:1px;background:currentColor}.menu-btn:before{top:18px}.menu-btn span{top:26px}.mobile-menu{display:none;position:fixed;z-index:80;inset:82px 0 0;background:#070707;padding:32px var(--pad)}.mobile-menu.open{display:block}.mobile-menu a{display:flex;justify-content:space-between;border-bottom:1px solid var(--line);padding:18px 0;font-size:clamp(28px,7vw,42px);letter-spacing:-.04em}.mobile-menu a:last-child{color:var(--red)}
.kicker{font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:var(--muted)}.btn{display:inline-flex;align-items:center;justify-content:center;min-height:48px;padding:13px 19px;border:1px solid rgba(255,255,255,.24);font-size:13px;transition:.25s var(--ease)}.btn:hover{transform:translateY(-2px);border-color:#fff}.btn.primary{background:var(--red);border-color:var(--red)}.reveal{opacity:0;transform:translateY(22px);transition:opacity .72s var(--ease),transform .72s var(--ease)}.reveal.in{opacity:1;transform:none}
/* HERO */
.hero{min-height:100svh;padding-top:82px;position:relative;overflow:hidden;display:flex;align-items:flex-end;background:#090909}.hero-media{position:absolute;inset:82px 0 0}.hero-media img{height:100%;object-fit:cover;object-position:center;filter:saturate(.92) contrast(1.04);transform:scale(1.035);will-change:transform}.hero-media:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(7,7,7,.22) 0%,rgba(7,7,7,.2) 35%,rgba(7,7,7,.86) 92%),linear-gradient(90deg,rgba(7,7,7,.75),transparent 55%)}.hero-shell{position:relative;z-index:2;width:min(var(--max),100%);margin:auto;padding:0 var(--pad) clamp(42px,5vw,74px)}.hero-meta{display:flex;justify-content:space-between;gap:20px;border-top:1px solid rgba(255,255,255,.26);padding-top:16px;margin-bottom:clamp(32px,4vw,60px)}.hero-meta span:last-child{color:#d5d1cb}.hero h1{font-size:clamp(64px,10.4vw,156px);line-height:.82;letter-spacing:-.075em;font-weight:520;margin:0;max-width:1260px}.hero h1 em{font-style:normal;color:var(--teal-bright)}.hero-bottom{margin-top:clamp(30px,4vw,56px);display:grid;grid-template-columns:1fr .7fr;gap:42px;align-items:end}.hero-lede{font-size:clamp(18px,1.35vw,22px);max-width:720px;color:#dedad4;letter-spacing:-.02em;margin:0}.hero-actions{justify-self:end;display:flex;gap:10px;align-items:center}.hero-stamp{position:absolute;right:var(--pad);top:22%;width:clamp(100px,11vw,168px);height:clamp(100px,11vw,168px);border:1px solid rgba(255,255,255,.36);border-radius:50%;display:grid;place-items:center;text-align:center;font-size:10px;letter-spacing:.18em;text-transform:uppercase;color:#e8e4de;transform:rotate(8deg);z-index:3}.hero-stamp:after{content:"";position:absolute;inset:9px;border:1px solid rgba(69,192,189,.55);border-radius:50%}
/* SNAPSHOT */
.snapshot{background:var(--paper);color:#101010;padding:clamp(74px,8vw,126px) 0}.snapshot-head{display:grid;grid-template-columns:.42fr 1.58fr;gap:48px;align-items:start}.snapshot h2{margin:0;font-size:clamp(44px,6.2vw,92px);line-height:.9;letter-spacing:-.065em;font-weight:520;max-width:1080px}.snapshot h2 em{font-style:normal;color:var(--teal)}.snapshot-grid{margin-top:clamp(58px,7vw,98px);display:grid;grid-template-columns:repeat(4,1fr);border-top:1px solid rgba(0,0,0,.2)}.fact{padding:20px 24px 0 0;border-right:1px solid rgba(0,0,0,.16);min-height:150px}.fact:not(:first-child){padding-left:24px}.fact:last-child{border-right:0}.fact small{display:block;font-size:10px;letter-spacing:.16em;text-transform:uppercase;color:#77726b;margin-bottom:18px}.fact strong{display:block;font-size:clamp(20px,1.8vw,28px);line-height:1.05;letter-spacing:-.035em;font-weight:520}.fact a{border-bottom:1px solid #111;padding-bottom:2px}
/* CHALLENGE */
.challenge{padding:clamp(90px,10vw,160px) 0;background:#080808}.challenge-grid{display:grid;grid-template-columns:.78fr 1.22fr;gap:clamp(60px,8vw,140px);align-items:start}.challenge-copy{position:sticky;top:122px}.challenge h2{font-size:clamp(52px,6.6vw,98px);line-height:.9;letter-spacing:-.068em;font-weight:520;margin:18px 0 28px}.challenge h2 span{color:var(--teal-bright)}.challenge p{max-width:610px;color:#c8c4be;font-size:clamp(17px,1.25vw,20px);margin:0}.challenge-visual{position:relative;min-height:760px}.challenge-visual .main{position:absolute;top:0;right:0;width:88%;height:72%;object-fit:cover;border-radius:4px}.challenge-visual .detail{position:absolute;left:0;bottom:0;width:54%;height:42%;object-fit:cover;border:10px solid #080808;border-radius:4px;box-shadow:0 20px 80px rgba(0,0,0,.5)}.challenge-note{position:absolute;right:4%;bottom:8%;width:min(300px,38%);background:var(--teal);color:#071010;padding:22px;font-size:14px;line-height:1.35}.challenge-note b{display:block;font-size:11px;letter-spacing:.16em;text-transform:uppercase;margin-bottom:18px}
/* SYSTEM STORY */
.system{height:420svh;position:relative;background:#0c0c0c}.system-sticky{position:sticky;top:82px;height:calc(100svh - 82px);display:grid;grid-template-columns:.9fr 1.1fr;overflow:hidden}.system-copy{padding:clamp(42px,5vw,74px) var(--pad);display:flex;flex-direction:column;border-right:1px solid rgba(255,255,255,.1);background:#0b0b0b}.system-top{display:flex;justify-content:space-between;gap:20px}.system-count{font-size:11px;letter-spacing:.16em;color:var(--teal-bright)}.system-stage{position:relative;flex:1;display:flex;align-items:center}.system-step{position:absolute;inset:auto 0;opacity:0;visibility:hidden;transform:translateY(18px);transition:opacity .45s var(--ease),transform .55s var(--ease),visibility .45s}.system-step.active{opacity:1;visibility:visible;transform:none}.system-step .num{font-size:11px;letter-spacing:.16em;color:#77726c;margin-bottom:18px}.system-step h3{font-size:clamp(50px,5.2vw,82px);line-height:.9;letter-spacing:-.065em;font-weight:520;margin:0 0 25px}.system-step p{color:#c9c5bf;max-width:540px;font-size:clamp(16px,1.15vw,19px);margin:0}.system-tags{margin-top:30px;display:flex;flex-wrap:wrap;gap:8px}.system-tags span{border:1px solid rgba(255,255,255,.18);padding:8px 11px;font-size:11px;color:#d7d3cd}.system-progress{display:grid;grid-template-columns:repeat(4,1fr);gap:5px}.system-progress i{height:2px;background:rgba(255,255,255,.13);position:relative;overflow:hidden}.system-progress i:after{content:"";position:absolute;inset:0;background:var(--teal-bright);transform:scaleX(0);transform-origin:left;transition:transform .45s var(--ease)}.system[data-state="0"] .system-progress i:nth-child(1):after,.system[data-state="1"] .system-progress i:nth-child(-n+2):after,.system[data-state="2"] .system-progress i:nth-child(-n+3):after,.system[data-state="3"] .system-progress i:nth-child(-n+4):after{transform:scaleX(1)}
.system-visual{position:relative;background:#0f0f0f;overflow:hidden}.system-shot{position:absolute;inset:6% 5%;border:1px solid rgba(255,255,255,.16);border-radius:6px;overflow:hidden;background:#171717;box-shadow:0 30px 100px rgba(0,0,0,.35)}.browser-bar{height:44px;display:flex;align-items:center;gap:7px;padding:0 14px;background:#111;border-bottom:1px solid rgba(255,255,255,.1)}.browser-bar i{width:7px;height:7px;border-radius:50%;background:#3d3d3d}.browser-bar span{font-size:10px;color:#85817b;margin-left:8px}.site-canvas{height:calc(100% - 44px);position:relative;overflow:hidden;background:#efeee8}.site-canvas img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;transition:transform .9s var(--ease),filter .7s var(--ease);transform:scale(1.03)}.site-overlay{position:absolute;inset:0;pointer-events:none;transition:.65s var(--ease)}.site-label{position:absolute;background:rgba(7,7,7,.88);color:#f7f3ed;padding:10px 12px;font-size:10px;letter-spacing:.12em;text-transform:uppercase;border-left:2px solid var(--teal-bright);opacity:0;transform:translateY(8px);transition:.45s var(--ease)}.site-label.one{left:8%;top:14%}.site-label.two{right:8%;top:28%}.site-label.three{left:12%;bottom:18%}.system[data-state="0"] .site-canvas img{transform:scale(1.03) translateY(0)}.system[data-state="0"] .site-label.one{opacity:1;transform:none}.system[data-state="1"] .site-canvas img{transform:scale(1.15) translate(-2%,6%)}.system[data-state="1"] .site-label.two{opacity:1;transform:none}.system[data-state="2"] .site-canvas img{transform:scale(1.23) translate(7%,-4%)}.system[data-state="2"] .site-label.three{opacity:1;transform:none}.system[data-state="3"] .site-canvas img{transform:scale(1.07) translateY(-7%);filter:saturate(.85)}.local-rail{position:absolute;left:5%;right:5%;bottom:5%;display:grid;grid-template-columns:repeat(4,1fr);background:rgba(7,7,7,.92);border:1px solid rgba(255,255,255,.16);opacity:0;transform:translateY(18px);transition:.6s var(--ease)}.local-rail span{padding:13px 14px;border-right:1px solid rgba(255,255,255,.12);font-size:10px;letter-spacing:.12em;text-transform:uppercase}.local-rail span:last-child{border-right:0}.system[data-state="3"] .local-rail{opacity:1;transform:none}
/* BRAND MOMENT */
.brand-moment{background:var(--teal);color:#071010;padding:clamp(72px,8vw,124px) 0;overflow:hidden}.brand-line{white-space:nowrap;width:100%;padding-inline:var(--pad);font-size:clamp(52px,6.7vw,112px);line-height:.82;letter-spacing:-.068em;font-weight:600;transform:none}.brand-line.outline{font-size:clamp(42px,5.15vw,86px);color:transparent;-webkit-text-stroke:1.4px rgba(7,16,16,.7);margin-top:clamp(14px,1.3vw,20px);transform:none}.brand-moment .shell{margin-top:clamp(56px,6vw,88px);display:grid;grid-template-columns:.62fr 1.38fr;gap:60px}.brand-moment h2{font-size:clamp(42px,5vw,74px);line-height:.92;letter-spacing:-.06em;margin:0;font-weight:520}.brand-moment p{margin:0;max-width:660px;font-size:clamp(17px,1.3vw,21px);line-height:1.52}
/* IA */
.ia{background:var(--paper);color:#111;padding:clamp(92px,10vw,156px) 0}.ia-head{display:grid;grid-template-columns:.52fr 1.48fr;gap:54px}.ia h2{font-size:clamp(48px,6.4vw,96px);line-height:.9;letter-spacing:-.066em;font-weight:520;margin:0}.ia h2 em{font-style:normal;color:var(--teal)}.ia-intro{max-width:760px;color:#4c4944;font-size:clamp(17px,1.3vw,21px);margin:28px 0 0}.ia-list{margin-top:clamp(58px,7vw,100px);border-top:1px solid rgba(0,0,0,.22)}.ia-row{display:grid;grid-template-columns:90px .9fr 1.1fr;gap:34px;padding:28px 0;border-bottom:1px solid rgba(0,0,0,.16);align-items:start}.ia-row .n{font-size:11px;letter-spacing:.16em;color:#7b756e}.ia-row strong{font-size:clamp(25px,2.25vw,34px);font-weight:520;letter-spacing:-.035em}.ia-row p{margin:0;color:#5e5a54;max-width:650px}
/* LOCAL */
.local{background:#090909;padding:clamp(92px,10vw,158px) 0}.local-grid{display:grid;grid-template-columns:.86fr 1.14fr;gap:clamp(50px,8vw,130px)}.local h2{font-size:clamp(50px,6.4vw,96px);line-height:.9;letter-spacing:-.067em;font-weight:520;margin:16px 0 28px}.local h2 span{color:var(--teal-bright)}.local p{color:#c8c4be;max-width:610px}.places{border-top:1px solid var(--line)}.place{display:flex;justify-content:space-between;gap:30px;padding:22px 0;border-bottom:1px solid var(--line);align-items:baseline}.place strong{font-size:clamp(24px,2.3vw,34px);font-weight:500;letter-spacing:-.035em}.place span{font-size:11px;color:#88837d;text-transform:uppercase;letter-spacing:.14em}
/* LIVE */
.live{background:#0e0e0e;padding:clamp(88px,9vw,144px) 0}.live-head{display:flex;justify-content:space-between;gap:40px;align-items:end;margin-bottom:48px}.live h2{font-size:clamp(50px,6.7vw,100px);line-height:.88;letter-spacing:-.068em;font-weight:520;margin:0}.live h2 span{color:var(--teal-bright)}.live-head p{max-width:440px;margin:0;color:#bbb7b1}.live-frame{position:relative;aspect-ratio:16/9;border:1px solid rgba(255,255,255,.16);border-radius:6px;overflow:hidden;background:#111}.live-frame img{height:100%;object-fit:cover;transition:transform 1.2s var(--ease),filter .7s var(--ease)}.live-frame:after{content:"Live Website ansehen ↗";position:absolute;right:20px;bottom:20px;background:#070707;color:#fff;padding:12px 15px;font-size:11px;letter-spacing:.13em;text-transform:uppercase;border-left:2px solid var(--teal-bright)}.live-frame:hover img{transform:scale(1.045);filter:saturate(1.08)}
/* NEXT */
.next{background:var(--paper);color:#111;padding:clamp(74px,8vw,122px) 0}.next-grid{display:grid;grid-template-columns:.52fr 1.48fr;gap:54px;align-items:end}.next h2{font-size:clamp(52px,7vw,108px);line-height:.86;letter-spacing:-.07em;font-weight:520;margin:0}.next h2 span{color:var(--red)}.next-row{margin-top:34px;display:flex;align-items:center;justify-content:space-between;gap:30px;border-top:1px solid rgba(0,0,0,.2);padding-top:20px}.next-row p{margin:0;color:#625e57}.next-link{font-size:12px;text-transform:uppercase;letter-spacing:.14em;border-bottom:1px solid #111;padding-bottom:4px}
.footer{padding:52px 0 24px;background:#070707;border-top:1px solid var(--line)}.footer-top{display:grid;grid-template-columns:1fr 1.3fr;gap:50px}.footer-brand{font-size:40px;letter-spacing:-.06em;font-weight:650}.footer-top p{color:#8d8881;max-width:320px}.footer-map{display:grid;grid-template-columns:repeat(3,1fr);gap:32px}.footer-map strong{display:block;font-size:11px;letter-spacing:.14em;text-transform:uppercase;margin-bottom:15px}.footer-map a,.footer-map span{display:block;color:#99948d;font-size:13px;padding:5px 0}.footer-bottom{margin-top:52px;padding-top:18px;border-top:1px solid var(--line);display:grid;grid-template-columns:1fr auto auto;gap:26px;color:#706b65;font-size:11px}.footer-bottom div{display:flex;gap:18px}
@media(max-width:1050px){.nav-links{display:none}.menu-btn{display:block}.snapshot-head,.challenge-grid,.ia-head,.local-grid,.next-grid{grid-template-columns:1fr}.snapshot-head{gap:22px}.challenge-copy{position:relative;top:auto}.challenge-visual{min-height:620px}.system{height:420svh}.system-sticky{grid-template-columns:1fr;height:calc(100svh - 82px)}.system-copy{border-right:0;border-bottom:1px solid rgba(255,255,255,.1);padding:28px var(--pad);min-height:43%}.system-visual{min-height:57%}.system-stage{min-height:200px}.system-step h3{font-size:clamp(38px,7vw,66px)}.system-shot{inset:5% 10%}.brand-moment .shell{grid-template-columns:1fr;gap:28px}.local-grid{gap:40px}.next-grid{gap:34px}}
@media(max-width:760px){.nav{height:72px}.mobile-menu{inset:72px 0 0}.hero{padding-top:72px;min-height:100svh}.hero-media{inset:72px 0 0}.hero-media img{object-position:60% center}.hero-media:after{background:linear-gradient(180deg,rgba(7,7,7,.28),rgba(7,7,7,.5) 50%,rgba(7,7,7,.94) 91%)}.hero-meta{flex-direction:column;gap:6px;margin-bottom:30px}.hero h1{font-size:clamp(56px,18vw,82px);line-height:.82}.hero-bottom{grid-template-columns:1fr;gap:26px}.hero-actions{justify-self:start;flex-wrap:wrap}.hero-stamp{display:none}.snapshot-grid{grid-template-columns:1fr 1fr}.fact{min-height:128px;padding:18px 14px 18px 0;border-bottom:1px solid rgba(0,0,0,.16)}.fact:nth-child(2){border-right:0;padding-left:18px}.fact:nth-child(3){padding-left:0}.fact:nth-child(4){border-right:0;padding-left:18px}.challenge{padding-bottom:80px}.challenge-visual{min-height:500px}.challenge-visual .main{width:100%;height:67%}.challenge-visual .detail{width:66%;height:37%;border-width:7px}.challenge-note{width:52%;right:0;bottom:4%;padding:15px;font-size:12px}.system{height:auto}.system-sticky{position:relative;top:auto;height:auto;display:block}.system-copy{padding:70px var(--pad) 42px}.system-top{margin-bottom:40px}.system-stage{display:block;min-height:0}.system-step{position:relative;opacity:1;visibility:visible;transform:none;padding:30px 0;border-top:1px solid var(--line)}.system-step:not(.active){opacity:.46}.system-progress{display:none}.system-visual{height:62svh;min-height:450px}.system-shot{inset:5% var(--pad)}.site-canvas img{transform:scale(1.06)!important;filter:none!important}.site-label,.local-rail{display:none}.brand-line{font-size:20vw}.brand-moment .shell{margin-top:50px}.ia-row{grid-template-columns:48px 1fr;gap:14px 18px}.ia-row p{grid-column:2}.live-head{display:block}.live-head p{margin-top:26px}.live-frame{aspect-ratio:4/3}.live-frame img{object-position:center}.next-row{align-items:flex-start;flex-direction:column}.footer-top{grid-template-columns:1fr}.footer-map{grid-template-columns:1fr 1fr}.footer-bottom{grid-template-columns:1fr;gap:12px}}
@media(max-width:430px){.snapshot-grid{grid-template-columns:1fr}.fact,.fact:nth-child(n){border-right:0;padding:18px 0}.challenge-visual{min-height:430px}.challenge-note{width:60%}.footer-map{grid-template-columns:1fr}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.reveal{opacity:1;transform:none;transition:none}.hero-media img,.site-canvas img,.live-frame img{transform:none!important;transition:none}.system{height:auto}.system-sticky{position:relative;top:auto;height:auto}.system-step{position:relative;opacity:1;visibility:visible;transform:none;padding:25px 0}.system-visual{min-height:520px}}

/* ===== Responsive QA rebuild V2 ===== */
.system-mobile-visual{display:none}

/* Tablet is still a two-column pinned case story. The previous vertical
   pinned layout compressed the browser preview between 761-1050px. */
@media (min-width:821px) and (max-width:1050px){
  .system{height:420svh}
  .system-sticky{grid-template-columns:minmax(0,.88fr) minmax(0,1.12fr);height:calc(100svh - 82px)}
  .system-copy{border-right:1px solid rgba(255,255,255,.1);border-bottom:0;padding:clamp(28px,3.8vw,44px)}
  .system-stage{min-height:0}
  .system-step h3{font-size:clamp(38px,5.25vw,54px);margin-bottom:18px}
  .system-step p{font-size:clamp(14px,1.75vw,17px);line-height:1.48}
  .system-tags{margin-top:20px;gap:6px}
  .system-tags span{padding:6px 8px;font-size:9px}
  .system-visual{min-height:0;display:grid;place-items:center;padding:clamp(20px,3vw,34px)}
  .system-shot{position:relative;inset:auto;width:100%;height:auto;aspect-ratio:1.36;max-height:72vh}
  .browser-bar{height:38px}
  .site-canvas{height:calc(100% - 38px)}
  .site-label{font-size:8px;padding:7px 9px}
  .local-rail{left:clamp(20px,3vw,34px);right:clamp(20px,3vw,34px);bottom:clamp(14px,2vw,24px)}
  .local-rail span{padding:9px 8px;font-size:8px}
}

/* Portrait tablet + phones: each idea and its proof stay together. */
@media (max-width:820px){
  .system{height:auto}
  .system-sticky{position:relative;top:auto;height:auto;display:block;overflow:visible}
  .system-copy{padding:clamp(64px,9vw,86px) var(--pad) clamp(52px,8vw,72px);border-right:0;border-bottom:0}
  .system-top{margin-bottom:34px}
  .system-count{display:none}
  .system-stage{display:block;min-height:0}
  .system-step,.system-step:not(.active){position:relative;inset:auto;opacity:1;visibility:visible;transform:none;padding:clamp(32px,5vw,48px) 0;border-top:1px solid var(--line)}
  .system-step:first-child{border-top:0;padding-top:0}
  .system-step h3{font-size:clamp(40px,8vw,62px);margin-bottom:18px}
  .system-step p{font-size:clamp(15px,2.2vw,18px);max-width:620px;overflow-wrap:anywhere;hyphens:auto}
  .system-progress,.system-visual{display:none}
  .system-mobile-visual{display:block;margin-top:clamp(24px,4vw,36px)}
  .mobile-browser{border:1px solid rgba(255,255,255,.16);border-radius:5px;overflow:hidden;background:#151515;box-shadow:0 22px 70px rgba(0,0,0,.28)}
  .mobile-browser .browser-bar{height:36px}
  .mobile-site{height:clamp(250px,52vw,390px);position:relative;overflow:hidden;background:#efeee8}
